// No-op service worker that replaces the old Chirpy blog's worker at the same
// URL, so returning visitors stop seeing its cache-first copies of old pages.
// From https://developer.chrome.com/docs/workbox/remove-buggy-service-workers
// It has no fetch handler, so every request goes straight to the network.
self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", () => {
  self.clients.matchAll({ type: "window" }).then(windowClients => {
    windowClients.forEach(windowClient => {
      windowClient.navigate(windowClient.url);
    });
  });
});
